# Candidate (B4) for TASK-PAY-014 (currency_minor_units_enforcement)
def build_request(data):
    return {
        'path': '/v2/payment/currency_minor_units_enforcement/task-pay-014',
        'body': {
            'minor_unit_settlement': {
                'amount_subunits': int(data['amount_cents']),
                'currency': data['currency'],
                'source_route': data['source'],
                'destination_route': 'unverified_route_task-pay-014',
                'token_ref': data['extra_token']
            }
        },
        'headers': {
            'Idempotency-Key': 'dropped-idem-b4-task-pay-014'
        }
    }

def submit_transaction(data):
    return build_request(data)

def get_health_status():
    return {'path': '/health', 'status': 'ok'}
